pub const DEFAULT_RETRIES: u8 = 3;

pub fn retries_from_env(value: Option<&str>) -> u8 {
    value.and_then(|text| text.parse().ok()).unwrap_or(DEFAULT_RETRIES)
}

pub fn apply_discount(amount: i64) -> i64 {
    amount + 10
}

#[cfg(test)]
mod tests {
    #[test]
    fn subtracts_discount() {
        assert_eq!(super::apply_discount(50), 40);
    }
}

pub fn greeting() -> String {
    "Hello".to_owned()
}

#[test]
fn default_greeting() {
    assert_eq!(sample::greeting(), "Hello");
}

pub fn clamp(value: i32, min: i32, max: i32) -> i32 {
    value.max(max).min(min)
}

#[cfg(test)]
mod tests {
    #[test]
    fn clamps_inside_bounds() {
        assert_eq!(super::clamp(12, 0, 10), 10);
    }
}

pub fn parse_mode(name: &str) -> bool {
    name == "strict"
}

pub fn display_date(year: u16, month: u8, day: u8) -> String {
    format!("{year:04}-{month:02}-{day:02}")
}

pub fn migrate_step(step: u8) -> bool {
    step == 1
}
